<?php
session_start();
require_once __DIR__ . '/../../inc/connection.php';
require_once __DIR__ . '/funcs.php';
$shift=(string)get_column('kp_shift','shift','1');if(!$shift||$shift==='0')$shift=date('Y-m-d');
$safe=mysqli_real_escape_string($connection,$shift);$bills=[];$q=mysqli_query($connection,"SELECT s.sale_id,s.amount,s.counter,s.user_id,u.username FROM kp_sales s LEFT JOIN kp_users u ON u.user_id=s.user_id WHERE s.shift='$safe' AND s.pay_status=2 ORDER BY s.sale_id DESC");while($q&&($r=mysqli_fetch_assoc($q)))$bills[]=['id'=>(int)$r['sale_id'],'amount'=>(float)$r['amount'],'counter'=>(int)$r['counter'],'user_id'=>(int)$r['user_id'],'user'=>(string)($r['username']??'Unknown')];
$modes=[];$q=mysqli_query($connection,"SELECT pay_id,name FROM kp_pay_mode WHERE del_status=2 ORDER BY name");while($q&&($r=mysqli_fetch_assoc($q)))$modes[]=$r;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>K-TOUCH | Cashier Desk</title><style>:root{--green:#19864c;--orange:#ff7925;--ink:#192630;--muted:#71808b;--line:#e4e9ec;--bg:#f4f6f5}*{box-sizing:border-box}body{margin:0;font:13px Arial,sans-serif;background:var(--bg);color:var(--ink)}button,input,select{font:inherit}button{cursor:pointer}header{height:60px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:20px;padding:0 24px;position:sticky;top:0;z-index:4}.logo{font-size:23px;font-weight:900;color:#0c603b}.logo b{color:var(--orange)}.logo small{font-size:11px;color:#fff;background:var(--orange);padding:4px;border-radius:5px}.head-pill{margin-left:auto;padding:10px 14px;border:1px solid var(--line);border-radius:9px;background:#fff}.layout{display:grid;grid-template-columns:270px minmax(0,1fr);gap:12px;padding:14px;max-width:1500px;margin:auto}.card{background:#fff;border:1px solid var(--line);border-radius:13px;box-shadow:0 3px 16px #172e3410;overflow:hidden}.card-title,.heading{padding:13px 15px;border-bottom:1px solid var(--line)}.side-items{padding:10px;display:grid;gap:8px}.side-btn{width:100%;border:1px solid #e6e9e9;border-radius:11px;background:#fff;text-align:left;padding:12px}.side-btn:hover{border-color:#ffad72;background:#fff9f4}.side-btn strong,.side-btn small{display:block}.side-btn .value{display:block;font-weight:900;font-size:21px;margin:4px 0}.side-btn small{font-size:10px;color:var(--muted)}.main{min-width:0;display:flex;flex-direction:column;gap:12px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.metric{padding:14px;min-height:90px}.metric label,.metric span{display:block;color:var(--muted);font-size:10px}.metric strong{display:block;font-size:21px;margin:8px 0}.heading h2{margin:0 0 4px;font-size:20px}.heading p{margin:0;color:var(--muted);font-size:11px}.filters{display:flex;gap:8px;padding:13px 15px;flex-wrap:wrap}.filters input,.filters select{padding:10px;border:1px solid var(--line);border-radius:8px}.filters input{flex:1;min-width:200px}.workspace{display:grid;grid-template-columns:1.7fr .8fr;gap:12px;padding:0 12px 12px}.desk,.selected{border:1px solid var(--line);border-radius:12px;overflow:hidden}.desk h3,.selected h3{margin:0;padding:13px;font-size:15px;border-bottom:1px solid var(--line)}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th{font-size:10px;background:#f1f5f7;padding:11px 9px;text-align:left}td{padding:10px 9px;border-top:1px solid #eef0f2;font-size:11px}td:last-child,th:last-child{text-align:right}.selected-inner{padding:12px}.summary{background:#fff9f2;border:1px solid #f4e6d7;border-radius:10px;padding:12px;display:flex;justify-content:space-between}.summary b{display:block;font-size:20px;margin-top:5px}.selected-list{min-height:210px;max-height:330px;overflow:auto;margin-top:12px;border:1px solid var(--line);border-radius:9px}.selected-row{display:flex;justify-content:space-between;padding:12px;border-bottom:1px solid var(--line)}.paybox{padding:12px;border-top:1px solid var(--line)}.paybox select,.paybox input{width:100%;padding:10px;margin:5px 0 9px;border:1px solid var(--line);border-radius:8px}.pay{width:100%;padding:12px;border:0;border-radius:8px;background:var(--green);color:#fff;font-weight:800}.empty{text-align:center;padding:45px;color:var(--muted)}.message{margin:0 12px;padding:10px;border-radius:7px;background:#e7f7ed;color:#14713f;display:none}@media(max-width:900px){.layout{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}.workspace{grid-template-columns:1fr}}@media(max-width:560px){header{padding:0 12px}.head-pill{display:none}.layout{padding:8px}.metrics{gap:6px}.metric{padding:10px}.metric strong{font-size:17px}.workspace{padding:0 6px 6px}}
</style></head><body><header><div class="logo"><b>K-</b>TOUCH <small>POS</small></div><div class="head-pill">Cashier · Shift <?php echo htmlspecialchars($shift); ?></div></header><div class="layout"><aside><section class="card"><div class="card-title"><b>Today</b></div><div class="side-items"><button class="side-btn" onclick="document.getElementById('desk').scrollIntoView({behavior:'smooth'})"><strong>CLEAR TODAY'S BILLS</strong><span class="value"><?php echo count($bills); ?></span><small>Unpaid bills waiting for clearance</small></button><a class="side-btn" href="index.php" style="display:block;text-decoration:none"><strong>FULL CASHIER DESK</strong><small>Open the complete cashier tools</small></a></div></section></aside><main class="main"><section class="metrics"><div class="card metric"><label>Unpaid Bills</label><strong id="billCount"><?php echo count($bills); ?></strong><span>Waiting for clearance</span></div><div class="card metric"><label>Total Amount</label><strong id="billTotal">KES 0.00</strong><span>Unpaid amount</span></div><div class="card metric"><label>Selected Bills</label><strong id="selectedCount">0</strong><span>Ready to clear</span></div><div class="card metric"><label>Selected Amount</label><strong id="selectedTotal">KES 0.00</strong><span>Payment required</span></div></section><section class="card"><div class="heading"><h2>Clear Current Bills</h2><p>Select a waiter or bill, then process the real payment through the cashier system.</p></div><div class="filters"><input id="search" placeholder="Search bill or waiter..."><select id="waiter"><option value="all">All Waiters</option><?php $seen=[];foreach($bills as $b){if(isset($seen[$b['user_id']]))continue;$seen[$b['user_id']]=1;?><option value="<?php echo $b['user_id'];?>"><?php echo htmlspecialchars($b['user']);?></option><?php }?></select></div><div class="workspace" id="desk"><section class="desk"><h3>Unpaid Bills</h3><div class="table-scroll"><table><thead><tr><th></th><th>Bill</th><th>Waiter</th><th>Counter</th><th>Amount</th></tr></thead><tbody id="rows"></tbody></table></div></section><section class="selected"><h3>Selected Bills</h3><div class="selected-inner"><div class="summary"><div><small>BILLS</small><b id="sumCount">0</b></div><div><small>TOTAL</small><b id="sumTotal">KES 0.00</b></div></div><div class="selected-list" id="selectedList"><div class="empty">Select bills from the list.</div></div><div class="paybox"><label>Payment mode<select id="payMode"><?php foreach($modes as $m):?><option value="<?php echo (int)$m['pay_id'];?>"><?php echo htmlspecialchars($m['name']);?></option><?php endforeach;?></select></label><label>Amount received<input id="received" type="number" min="0" step="0.01"></label><button class="pay" id="pay">CLEAR SELECTED BILLS</button></div></div></section></div><p class="message" id="message"></p></section></main></div><script>var bills=<?php echo json_encode($bills,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>,selected=new Set(),money=function(n){return 'KES '+Number(n||0).toLocaleString('en-KE',{minimumFractionDigits:2,maximumFractionDigits:2})};function visible(){var q=document.getElementById('search').value.toLowerCase(),w=document.getElementById('waiter').value;return bills.filter(function(b){return !selected.has(b.id)&&(!q||('#'+b.id+' '+b.user).toLowerCase().indexOf(q)>-1)&&(w==='all'||String(b.user_id)===w)})}function render(){var list=visible();document.getElementById('rows').innerHTML=list.length?list.map(function(b){return '<tr><td><input type="checkbox" data-id="'+b.id+'" data-amount="'+b.amount+'"></td><td><b>#'+b.id+'</b></td><td>'+b.user+'</td><td>'+b.counter+'</td><td>'+money(b.amount)+'</td></tr>'}).join(''):'<tr><td colspan="5" class="empty">No unpaid bills found.</td></tr>';var chosen=bills.filter(function(b){return selected.has(b.id)}),total=chosen.reduce(function(s,b){return s+b.amount},0);document.getElementById('selectedCount').textContent=chosen.length;document.getElementById('selectedTotal').textContent=money(total);document.getElementById('sumCount').textContent=chosen.length;document.getElementById('sumTotal').textContent=money(total);document.getElementById('billTotal').textContent=money(bills.reduce(function(s,b){return s+b.amount},0));document.getElementById('selectedList').innerHTML=chosen.length?chosen.map(function(b){return '<div class="selected-row"><span>#'+b.id+' · '+b.user+'</span><b>'+money(b.amount)+'</b></div>'}).join(''):'<div class="empty">Select bills from the list.</div>';document.querySelectorAll('#rows input').forEach(function(x){x.onchange=function(){selected.add(Number(x.dataset.id));render()}})}document.getElementById('search').oninput=render;document.getElementById('waiter').onchange=render;document.getElementById('pay').onclick=function(){var chosen=bills.filter(function(b){return selected.has(b.id)}),total=chosen.reduce(function(s,b){return s+b.amount},0),received=Number(document.getElementById('received').value||0);if(!chosen.length||received<total){alert('Select bills and enter the full amount received.');return}var fd=new FormData();fd.append('invoices',chosen.map(function(b){return b.id}).join(','));fd.append('grand_total',total);fd.append('tendered',received);fd.append('balance',0);fd.append('type',1);fd.append('orduser',chosen[0].user_id);fd.append('pay-mode[]',document.getElementById('payMode').value);fd.append('name'+document.getElementById('payMode').value,received);fd.append('ref'+document.getElementById('payMode').value,'');fetch('pay.php',{method:'POST',body:fd}).then(function(r){return r.json()}).then(function(r){if(r.status==='success'){location.reload()}else alert(r.message||'Payment failed')}).catch(function(){alert('Payment request failed')})};render();</script></body></html>
